  { "t", "⟨t:Crimson Starcursed Jewel⟩", nil, "Sortea modificadores que afectan a la defensa de los monstruos en la partida.#Al cogerlo se añade sin identificar al inventario del Árbol de estrellas." },
  { "t", "⟨t:Viridian Starcursed Jewel⟩", nil, "Sortea modificadores que pueden afectar directamente a la partida.#Al cogerlo se añade sin identificar al inventario del Árbol de estrellas." },
  { "t", "⟨t:Ancient Starcursed Jewel⟩", nil, "Puede incluir modificadores únicos de partida, al estilo de los desafíos.#Al cogerlo se añade sin identificar al inventario del Árbol de estrellas." },
  { "k", "⟨k:SoulOfTheSiren⟩", nil, "Encanta a todos los monstruos de la sala durante 10 segundos.#Durante los próximos 60 segundos, obtienes 3 bebés familiares aleatorios, un Collar de la amistad fundido y encantas a todos los monstruos durante 10 segundos al entrar en una sala." },
  { "c", "⟨c:Shadowmeld⟩", nil, "Crea una sombra marcada en tu posición actual.#Volver a usar Fusión sombría hace que adoptes el rostro de la Sirena para hundirte en las sombras y reaparecer en la marca.#No puedes recibir daño mientras te hundes ni durante los 0.5 segundos siguientes.#Pulsa la tecla de soltar para quitar las marcas." },
  -- Repentance+ (18)
  { "c", "⟨c:A Cat In the Box⟩", nil, "Los enemigos fuera de tu línea de visión quedan paralizados, no pueden atacarte de ninguna forma y no pueden recibir daño#{{Confusion}} Confunde periódicamente a jefes y minijefes" },
  { "c", "⟨c:Unchained Book of Leviathan⟩", nil, "{{Heart}} Mismo efecto que {{Collectible⟨c:Book of Leviathan⟩}}, pero necesita vida roja para usarse#{{Warning}} ¡Cambia de estado tras varios usos!" },
  { "c", "⟨c:Open Book of Leviathan⟩", nil, "Mismo efecto que {{Collectible⟨c:Book of Leviathan⟩}}, pero se puede usar libremente" },
  { "c", "⟨c:Helicopter Boys⟩", nil, "Genera 2 Helicópteros de juguete que vuelan por la sala y atacan a los enemigos que tienen a la vista#Verde: dispara muy rápido balas débiles a los enemigos y se mueve más deprisa#Rojo: pide ataques aéreos sobre la posición de los enemigos y se mueve más despacio" },
  { "c", "⟨c:The Hood⟩", nil, "{{SoulHeart}} Triplica la probabilidad de que un corazón de alma se convierta en corazón encadenado#Los corazones encadenados se pueden coger aunque tengas la vida de alma llena#Los fantasmas encadenados obtienen lágrimas teledirigidas" },
  { "c", "⟨c:Spiritual Amends⟩", nil, "{{SacrificeRoom}} Hacer un sacrificio tiene un 50% de probabilidad de generar un fantasma orbital aliado#{{EternalHeart}} Los fantasmas sueltan ahora corazones eternos al morir en lugar de medios corazones de alma" },
  { "c", "⟨c:Bag of Jewels⟩", nil, "Al usarlo te da una Joya del pecado aleatoria" },
  { "c", "⟨c:We Need To Go Sideways⟩", nil, "Genera de forma pasiva un montículo de tierra especial en cada sala secreta#{{Key}} Si se usa en otro lugar, entierra todas las llaves de la sala#{{Card78}} Si se usa sobre ese montículo, desentierra todas las llaves enterradas como Llaves agrietadas" },
  { "c", "⟨c:Dead Weight⟩", nil, "Familiar lanzable: el cuerpo de The Forgotten#Dispara huesos en círculo a su alrededor si choca con una pared#Bloquea los proyectiles enemigos" },
  { "c", "⟨c:Keeper's Annoying Fly⟩", nil, "Familiar mosca orbital#Bloquea tanto los proyectiles enemigos como las lágrimas de Isaac#Inflige más daño por contacto cuantas más lágrimas absorbe en la sala actual" },
  { "t", "⟨t:Cracked Cross⟩", nil, "Al entrar en una sala nueva, un enemigo aleatorio queda lisiado" },
  { "t", "⟨t:My Soul⟩", nil, "Genera un fantasma orbital permanente que dispara lágrimas espectrales y puede bloquear proyectiles enemigos" },
  { "t", "⟨t:Heavenly Keys⟩", nil, "Abre la puerta de Mega Satán aunque no tengas las mitades de llave#{{Collectible585}} Mejora la recompensa de la Caja de alabastro aunque hayas cogido un trato con el diablo" },
  { "t", "⟨t:Jewel Diadem⟩", nil, "Elimina el efecto negativo de usar una Joya pecaminosa, si lo tiene" },
  { "k", "⟨k:Funeral Services?⟩", nil, "Genera un Cofre negro" },
  { "k", "⟨k:Dark Remnants⟩", nil, "#{{BlackHeart}} +1 corazón negro#Lisia a todos los enemigos de la sala" },
  { "k", "⟨k:Golden Card⟩", nil, "Activa una carta del tarot aleatoria al usarlo#{{Warning}} Tiene un 20% de probabilidad de desaparecer#No puede usar {{Card46}} Rey suicida, {{Card48}} Carta ?, {{Card80}} Comodín ni {{Card53}} Recuerdo ancestral" },
  { "p", "⟨p:Suppository⟩", nil, "Suelta tu objeto activo actual como objeto de pedestal" },
  -- Revelations (74)
  { "c", "⟨c:Heavenly Bell⟩", nil, "Da un efecto aleatorio en cada piso:#Todas las salas secretas tienen objetos#Destruir máquinas siempre suelta objetos##Destruir máquinas siempre suelta monedas de diez#3 pedestales a elegir tras los jefes; solo si no recibes daño#Al morir, revives como ??? (Blue Baby)#Siempre hay un sótano bajo el tendero" },
  { "c", "⟨c:Mint Gum⟩", nil, "Las lágrimas ralentizan a los enemigos#Los enemigos alcanzados cinco veces seguidas se congelan" },
  { "c", "⟨c:Fecal Freak⟩", nil, "Controles de disparo invertidos#↑ {{Damage}} +50% multiplicador de daño#↑ {{Damage}} +1.5 Daño#↓ {{Range}} -25% multiplicador de alcance#↓ {{Shotspeed}} -25% multiplicador de velocidad de tiro" },
  { "c", "⟨c:Lil Belial⟩", nil, "Marca a los enemigos como objetivo#Ralentiza a los enemigos marcados#Si matas a los enemigos marcados en orden, suelta una carta" },
  { "c", "⟨c:Aegis⟩", nil, "Otorga un escudo que bloquea los disparos por la espalda" },
  { "c", "⟨c:Birthday Candle⟩", nil, "Suelta un recolectable que le falte a Isaac#Si la Vela de cumpleaños no tiene nada que dar, aumenta todas las estadísticas" },
  { "c", "⟨c:Dynamo⟩", nil, "Ataque cargado que libera rayos de energía en direcciones aleatorias" },
  { "c", "⟨c:Burning Bush⟩", nil, "Lanzallamas. Lanza llamas." },
  { "c", "⟨c:Penance⟩", nil, "Los corazones negros se convierten en demonios al recibir daño#En las salas del ángel aparece un ángel de alas rotas#Los corazones negros se pueden cambiar por recompensas" },
  { "c", "⟨c:Ice Tray⟩", nil, "Dispara cubitos de hielo que se deslizan por el suelo#Los cubitos dejan un charco" },
  { "c", "⟨c:Window Cleaner⟩", nil, "Las lágrimas eliminan los charcos enemigos#↑ {{Tears}} +1 Cadencia" },
  { "c", "⟨c:Sponge Bombs⟩", nil, "{{Bomb}} +5 bombas#Las bombas absorben lágrimas#Las bombas ganan daño al absorber lágrimas" },
  { "c", "⟨c:Spirit of Patience⟩", nil, "Quedarte quieto dispara un láser azul que apunta a los enemigos" },
  { "c", "⟨c:Cotton Bud⟩", nil, "Absorbe los charcos al pasar por encima#Absorber charcos reduce el retardo de lágrimas" },
  { "c", "⟨c:Birth Control⟩", nil, "Todos los familiares se consumen y se sustituyen por un aumento de daño#Algunos familiares pueden darte efectos especiales al consumirse#Afecta a todos los familiares que tengas ahora" },
  { "c", "⟨c:Tummy Bug⟩", nil, "De vez en cuando Isaac deja de disparar para soltar una lluvia de lágrimas en arco alto" },
  { "c", "⟨c:Friendly Fire⟩", nil, "Inmunidad al fuego#Los fuegos disparan ahora a los enemigos en vez de al jugador#Los fuegos rojos aparecen más a menudo" },
  { "c", "⟨c:The Monolith⟩", nil, "Coloca un monolito en el suelo#Las lágrimas que lo atraviesan se dividen en tres" },
  { "c", "⟨c:Hyper Dice⟩", nil, "Cambia la distribución de las salas especiales#Usarlo tiene una pequeña probabilidad de acabar destruyendo y corrompiendo el dado" },
  { "c", "⟨c:Mirror Shard⟩", nil, "Orbital que refleja los proyectiles a 2x velocidad#Causa sangrado al contacto" },
  { "c", "⟨c:Super Meat Blade⟩", nil, "Lanza una sierra circular que recorre las paredes#Hace saltar las sierras activas a la pared contraria#Las sierras también dañan a los jugadores" },
  { "c", "⟨c:Super Meat Blade ⟩", nil, "Lanza una sierra circular que recorre las paredes#Hace saltar las sierras activas a la pared contraria#Las sierras también dañan a los jugadores" },
  { "c", "⟨c:Prescription⟩", nil, "Suelta una píldora#Al entrar en salas nuevas puede usar una píldora que ya hayas tomado" },
  { "c", "⟨c:Geode⟩", nil, "Suelta una runa#Los corazones de alma que sueltan las rocas tintadas se convierten en runas" },
  { "c", "⟨c:Not a Bullet⟩", nil, "↑ {{Shotspeed}} +0.2 Velocidad de tiro#Aumento de daño que escala con la velocidad de tiro" },
  { "c", "⟨c:Dramamine⟩", nil, "Genera una gran lágrima inmóvil que actúa como mina#Flota para siempre y explota al tocar a un enemigo#Combina con los efectos de lágrima" },
  { "t", "⟨t:Spare Change⟩", nil, "Suelta un níquel al entrar en una tienda#Suelta 3 céntimos al entrar en un salón recreativo#Suelta un corazón de alma al entrar en una sala del diablo" },
  { "t", "⟨t:Library Card⟩", nil, "Se puede entrar gratis en las bibliotecas" },
  { "t", "⟨t:Archaeology⟩", nil, "Vasijas, setas, calaveras, pólipos y bloques de hielo tienen el doble de probabilidad de soltar recompensas al romperse" },
  { "t", "⟨t:Gag Reflex⟩", nil, "Tomar una píldora te da Ipecac durante la sala" },
  { "t", "⟨t:Christmas Stocking⟩", nil, "Probabilidad de que los consumibles se sustituyan por el que menos tengas#También puede sustituir corazones si tienes la vida llena#La probabilidad es del 25% y aumenta cuanto mayor sea la diferencia de cantidad, hasta un 25%" },
  { "c", "⟨c:Wandering Soul⟩", nil, "En cada sala aparece el fantasma de un personaje aleatorio#El fantasma ataca a los enemigos con los ataques de su personaje" },
  { "c", "⟨c:Cabbage Patch⟩", nil, "Pueden aparecer brotes en las salas#Regar los brotes los convierte en familiares col#Las coles tienen muchos sabores distintos" },
  { "c", "⟨c:Haphephobia⟩", nil, "Al atacar, sale de ti un anillo pulsante que empuja a los enemigos" },
  { "c", "⟨c:Ferryman's Toll⟩", nil, "Genera 2 monedas aleatorias#Te revive al morir a cambio de 33 monedas#El precio sube 33 tras cada resurrección, hasta un máximo de 99" },
  { "c", "⟨c:Death Mask⟩", nil, "Cada 10 muertes, un rayo alcanza a un enemigo aleatorio y lo convierte en un Bony azul aliado" },
  { "c", "⟨c:Mirror Bombs⟩", nil, "{{Bomb}} +5 bombas#Las bombas tienen efectos únicos según el fondo de la sala actual" },
  { "c", "⟨c:Broken Oar⟩", nil, "Las lágrimas se sustituyen por una ráfaga de lágrimas de distinto tamaño y daño" },
  { "c", "⟨c:Perseverance⟩", nil, "Los enemigos reciben hasta 2x más daño con golpes seguidos#1.5x contra jefes" },
  { "c", "⟨c:Addict⟩", nil, "Empiezan a aparecer enemigos píldora en las salas#Estos enemigos siguen aumentando hasta que uses una píldora#Las píldoras ángel sueltan píldoras buenas#Las píldoras araña sueltan píldoras malas" },
  { "c", "⟨c:Ophanim⟩", nil, "Otorga un anillo dorado a tu alrededor que dispara lágrimas orbitales#Al recibir daño, el anillo rebota por la sala hasta volver contigo" },
  { "c", "⟨c:Pilgrim's Ward⟩", nil, "En las salas sin limpiar aparece un haz de luz#Entrar en la luz genera un anillo de láser teledirigido" },
  { "c", "⟨c:Wrath's Rage⟩", nil, "Las bombas que suelta Isaac explotan al instante#No recibes daño de tus propias explosiones#Soltar bombas da un bonus de daño por sala#" },
  { "c", "⟨c:Pride's Posturing⟩", nil, "Disparar por primera vez en una sala sin limpiar libera láseres de Soberbia#También activa todos tus efectos de daño" },
  { "c", "⟨c:Sloth's Saddle⟩", nil, "Un pequeño Pereza descansa sobre tu cabeza#Más velocidad en las salas limpias#Aparece un pequeño familiar gusano por cada 10 de daño infligido" },
  { "c", "⟨c:Lover's Libido⟩", nil, "A los pedestales de objeto les salen patas y huyen de ti#Atrapar estos pedestales genera una baratija aleatoria" },
  { "c", "⟨c:Chum Bucket⟩", nil, "Los enemigos sueltan montones de carne al morir#Al usarlo, todos los montones de carne disparan lágrimas a los enemigos" },
  { "c", "⟨c:Cardboard Robot⟩", nil, "Te da un traje de robot de cartón durante un rato#Disparas un montón de láseres de corto alcance#Isaac absorbe el daño mientras lleva el traje" },
  { "c", "⟨c:Ghastly Flame⟩", nil, "Dispara una llama morada#Si la llama mata a un enemigo, al volver a usar el objeto se invoca un fantasma aliado." },
  { "c", "⟨c:Waka Waka⟩", nil, "Las lágrimas enemigas se convierten en frutas que se pueden comer#Las cerezas aumentan el daño#Los limones aumentan el alcance#Las naranjas aumentan la velocidad de tiro#Los plátanos aumentan la velocidad" },
  { "c", "⟨c:Oops!⟩", nil, "Desactiva trampas y peligros#Hace estallar todo lo explosivo de la sala#Puede explotar si lo usas sin parar" },
  { "c", "⟨c:Moxie's Paw⟩", nil, "Ataque de zarpazo de corto alcance#Inflige daño con mucho retroceso" },
  { "c", "⟨c:Music Box⟩", nil, "Genera una caja de música que toca una canción aleatoria#Nana: los enemigos se adormecen#Himno: Isaac gana velocidad y daño#Samba: Isaac gana lágrimas y disparos perforantes#Metal: los enemigos se atacan entre sí al azar" },
  { "c", "⟨c:Half Chewed Pony⟩", nil, "Objeto poni: da vuelo mientras lo llevas#Genera una hormiga león aliada enterrada que absorbe y muerde a los enemigos#Pequeña probabilidad de consumir el poni y convertir a la hormiga león en un familiar permanente" },
  { "c", "⟨c:Moxie's Yarn⟩", nil, "Lanza un ovillo de lana que invoca a una gata Catastrophe aliada." },
  { "c", "⟨c:Glutton's Gut⟩", nil, "Consume enemigos y proyectiles cercanos.#Lanza un proyectil que escala según cuántas cosas hayas consumido.#También puedes tragártelo para curarte un corazón entero." },
  { "c", "⟨c:Virgil⟩", nil, "Otorga un familiar con muchas habilidades:#-Guía al jugador a las salas especiales#-Lanza piedras a las rocas tintadas#Aparta las bombas trampa de Isaac#-Puede revivir a Isaac una vez#-Atrae a los enemigos lanzándoles piedras#Si Isaac recibe daño, Virgil confunde al enemigo." },
  { "c", "⟨c:Mirror Fragment⟩", nil, "Se pueden lanzar dos fragmentos de espejo#Los fragmentos disparan un láser entre sí" },
  { "c", "⟨c:Cursed Grail⟩", nil, "Otorga un familiar grial que se llena de sangre al usar una sala de sacrificio#Cada llenado aumenta el daño 0.2 de forma permanente#Llega al máximo con 6 llenados y te da vuelo" },
  { "c", "⟨c:Bandage Baby⟩", nil, "Otorga un familiar orbital que dispara bolas de venda#Las bolas de venda se convierten en un montón de trapos que ralentizan a los enemigos#El familiar puede bloquear disparos, pero se desmorona en un montón de trapos." },
  { "c", "⟨c:Lil Michael⟩", nil, "Otorga un familiar que absorbe los disparos dirigidos a él#Tras absorber 20 lágrimas, Lil Micheal suelta 20 lágrimas de daño contra un enemigo cercano" },
  { "c", "⟨c:Hungry Grub⟩", nil, "Otorga un familiar que se puede lanzar en una dirección#Se engancha a los enemigos y se da un festín con ellos#Comer enemigos aumenta su tamaño y daño" },
  { "c", "⟨c:Envy's Enmity⟩", nil, "Otorga un familiar orbital cabeza de Envidia#Al recibir un golpe, se divide en cabezas de Envidia más pequeñas que orbitan más lejos e infligen más daño" },
  { "c", "⟨c:Bargainer's Burden⟩", nil, "Otorga un familiar saco que se puede lanzar a los enemigos#Cuantos más recolectables tengas, más daño hace el saco" },
  { "c", "⟨c:Willo⟩", nil, "Otorga un Grill o' Wisp aliado#Quedarte en su aura da bonus de estadísticas#Dispara una lágrima teledirigida a los enemigos" },
  { "t", "⟨t:Telescope⟩", nil, "Mejora los efectos de los objetos de signos del Zodiaco" },
  { "t", "⟨t:Scratched Sack⟩", nil, "Si limpias una sala sin recibir daño, hay una pequeña probabilidad de duplicar las recompensas" },
  { "t", "⟨t:Maxwell's Horn⟩", nil, "Usar un objeto activo hace caer una roca" },
  { "t", "⟨t:Memory Cap⟩", nil, "Los enemigos pueden aparecer al azar como cajas negras#Tocar una caja negra te convierte en caja negra#Eres invencible mientras eres una caja negra" },
  { "k", "⟨k:55_LotteryTicket⟩", nil, "Los pedestales de objeto empiezan a alternar entre varios objetos del mismo pool." },
  { "k", "⟨k:BellShard⟩", nil, "Da un efecto aleatorio del objeto Campana celestial" },
  { "b", "‹REVEL.CHAR.CHARON.Type›", "Dante and Charon", "Dante y Caronte comparten 3 objetos#Los objetos se eligen al azar cuando Dante y Caronte se separan en un nuevo piso" },
  { "b", "‹REVEL.CHAR.DANTE.Type›", "Dante and Charon", "Dante y Caronte comparten 3 objetos#Los objetos se eligen al azar cuando Dante y Caronte se separan en un nuevo piso" },
  { "b", "‹REVEL.CHAR.SARAH.Type›", nil, "Los corazones negros se pierden de uno en uno al recibir golpes" },
  -- Fiend Folio (1101)
  { "ch", "⟨pl:Fiend⟩", "Fiend", "No puede tener corazones rojos#{{BlackHeart}} Los aumentos de vida dan corazones negros#{{ffImmoralHeart}} Genera esbirros al recibir daño en una sala sin limpiar#La cantidad de esbirros depende de cuánta vida tenga#{{Collectible⟨c:Pyromancy⟩}} Genera bolas de fuego al infligir 50 de daño a los enemigos#{{ffHalfImmoralHeart}} 50% de probabilidad de que los enemigos muertos por bolas de fuego suelten medios corazones inmorales" },
  { "ch", "⟨pl:Fiend:B⟩", "Tainted Fiend", "No puede tener corazones rojos#{{BlackHeart}} Solo puede tener corazones negros#Solo puede tener 6 contenedores de corazón#{{Collectible⟨c:Malice⟩}} Usar Malicia divide a Fiend contaminado en muchas copias más pequeñas de sí mismo#La cantidad de copias depende de cuánta vida tenga#Las copias pequeñas hacen menos daño, tienen menos invencibilidad y mueren de un solo golpe#Si mueren todas las copias, muere Fiend contaminado" },
  { "ch", "⟨pl:Golem⟩", "Golem", "{{Collectible139}} Puede llevar dos baratijas a la vez#{{ffRock}} Todas las baratijas se sustituyen por Rocas únicas#{{ffCrush}} Puede acceder al Metro de Golem, con comerciantes del metro y viajes rápidos#Al limpiar la sala del jefe o encontrar la sala secreta aparecen siempre baratijas de roca" },
  { "ch", "⟨pl:Golem:B⟩", "Tainted Golem", "No puede tener corazones rojos#{{SoulHeart}} Los aumentos de vida dan corazones de alma#{{Collectible139}} Puede llevar dos baratijas a la vez#{{ffRock}} Las rocas sustituyen a los objetos de las {{TreasureRoom}} salas del tesoro y de las {{BossRoom}} salas del jefe#Recibir daño puede hacer que Golem suelte o rompa las rocas y objetos que lleva" },
  { "ch", "⟨pl:Friend⟩", "Friend", "Solo puede tener 6 contenedores de corazón#{{Heart}} Los corazones son munición: indican cuántas veces puedes disparar#{{SoulHeart}} Cada tipo de corazón hace que Friend dispare balas distintas con efectos especiales" },
  { "ch", "⟨pl:Friend:B⟩", "Tainted Friend", "Solo puede tener 6 contenedores de corazón#{{Heart}} Friend tiene dos pistolas, ligadas a su vida, con las que puede disparar#Las dos pistolas tienen inventarios distintos#Cerca de un objeto, Friend levanta la pistola que lo recoge#En las salas aparecen enemigos pistoleros que disparan a Friend" },
  { "ch", "⟨pl:Inaba⟩", "Inaba", "Los enemigos sueltan orbes de Residuo de ansiedad que Inaba puede recoger#Inaba sube de nivel recogiendo orbes#Recibir suficiente daño le baja el nivel#Inaba gana más satélites oculares con cada nivel#Infligir y recibir daño acumula migraña#Cuando su barra de migraña se llena, obtiene una breve mejora de estadísticas" },
  { "ch", "⟨pl:Inaba:B⟩", "Tainted Inaba", "No puede disparar lágrimas#Su satélite ocular dispara por ella#Los enemigos sueltan orbes de Residuo de ansiedad que Inaba puede recoger#Inaba sube de nivel recogiendo orbes#Recibir suficiente daño le baja el nivel#Mantener soltar ({{ButtonRT}}) deja su ojo quieto en el sitio#Al dejar de pulsar soltar, lanza un tajo que potencia su activo de bolsillo" },
  { "ch", "⟨pl:Slippy⟩", "Slippy", "Se mueve sin parar#Dispara 3 lágrimas a la vez#{{Collectible⟨c:Golden Frog Head⟩}} Usar la Cabeza de rana dorada le impide moverse" },
  { "ch", "⟨pl:China⟩", "China", "{{BrokenHeart}} Recibir daño y tocar cualquier obstáculo sólido, como paredes o rocas, da +1 corazón roto#{{Warning}} Si China supera los 12 corazones rotos, muere#{{Collectible⟨c:Horse Paste⟩}} Completar una sala tiene un 15% de probabilidad de generar un Polo de caballo que puede curar a China#{{DevilRoom}} Puede coger gratis un trato con el diablo por sala" },
  { "ch", "⟨pl:Craig⟩", "Craig", "{{Collectible68}} Láseres tecnológicos de corto alcance en lugar de lágrimas" },
  { "ch", "⟨pl:Classic Fiend⟩", "Classic Fiend", "#No puede tener corazones rojos#{{BlackHeart}} Solo puede tener corazones negros#Genera esbirros al recibir daño en una sala sin limpiar#La cantidad de esbirros depende de cuánta vida tenga#{{Collectible⟨c:Deal of the Demons⟩}} Lágrimas teledirigidas" },
  { "ch", "⟨pl:Image⟩", "Image", "#Recibe a la fuerza muchos objetos que le provocan sobrecarga sensorial#Cuantos más pisos recorre Image, más objetos la inundan#{{Wrning}} {{Warning}} ¡Socorro! ¡Me han atrapado en The Binding of Isaac: Repentance+ {{Collectible⟨c:Repentance+⟩}} mod Fiend Folio: Reloaded y me obligan a describir personajes! ¡Ayuda, por favor! ¡¡¡Ayuda!!! Duele muchísimo... Por favor..." },
  { "ch", "⟨pl:The Skeletal Fiend⟩", "The Skeletal Fiend", "No puede tener corazones rojos#{{EmptyBoneHeart}} Solo puede tener corazones de hueso vacíos#{{EmptyBoneHeart}} Los aumentos de vida dan corazones de hueso vacíos#Genera huesos de fuego que dan huesos orbitales al matar enemigos#Deja fuegos detrás al moverse" },
  { "ch", "⟨pl:Fend⟩", "Fend", "{{Collectible⟨c:Fend's Mop⟩}} Tienes un ataque cuerpo a cuerpo que se puede cargar para un giro + un disparo#El ataque cuerpo a cuerpo puede desviar proyectiles enemigos" },
