  { "t", "⟨t:Mineral Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Al empujar contra una roca:#↑ +0.2 Velocidad#↑ +1.5 Daño#↑ +0.72 Lágrimas#↑ +1 Alcance#↑ +0.2 Velocidad de tiro#↑ +4 Suerte" },
  { "t", "⟨t:Thorny Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera una onda expansiva radial al recibir daño" },
  { "t", "⟨t:Time-lost Diamond⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Collectible422}} Al recibir un golpe, devuelve a Isaac a la sala anterior y revierte todo lo hecho en la sala#Si te golpean de nuevo en la misma sala, la baratija de roca no se activa" },
  { "t", "⟨t:Obsidian Grindstone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +2.5 Daño#↑ +0.36 Lágrimas#Las estadísticas se duplican si llevas otra baratija de roca#Cada 10 lágrimas disparadas cambia la otra baratija de roca que lleves, si la hay#{{Trinket⟨t:Pocket Sand⟩}} 15% de probabilidad de que la otra baratija se convierta en Arena de bolsillo" },
  { "t", "⟨t:God's Marble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#3% de probabilidad de disparar una lágrima espectral amarilla que deja un aura sagrada en el suelo#Cuando un enemigo toca el aura, 9 rayos de luz lo dañan#{{Damage}} Los rayos infligen 2.5 de daño por golpe#{{Luck}} 40% de probabilidad con 37 de suerte" },
  { "t", "⟨t:Twenty-Sided Emerald⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Timer}} Quedarte quieto junto a un recolectable lo cambia cada 3 segundos#Cada recolectable solo se puede cambiar hasta 3 veces" },
  { "t", "⟨t:Technological Ruby 2.0⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Otorga 2 anillos de láser en la posición de Isaac#El anillo interior inflige 0.1x el daño de Isaac#El anillo exterior inflige 0.25x el daño de Isaac" },
  { "t", "⟨t:Leaky Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Isaac deja un rastro de lágrimas inmóviles al moverse" },
  { "t", "⟨t:Twin Tuffs⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#25% de probabilidad de convertir los recolectables en su versión doble#{{Luck}} 100% de probabilidad con 30 de suerte#15% de probabilidad de duplicar las recompensas de la sala#{{Luck}} 100% de probabilidad con 57 de suerte" },
  { "t", "⟨t:Wetstone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera 7 burbujas al entrar en una sala#Recibir daño genera 10 burbujas más" },
  { "t", "⟨t:Stromatolite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{HalfHeart}} Las rocas tienen un 2.5% de probabilidad de soltar medio corazón al romperse#{{HalfSoulHeart}} Las rocas tintadas tienen un 25% de probabilidad de soltar medio corazón de alma extra" },
  { "t", "⟨t:Ribbed Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{EmptyBoneHeart}} Da un corazón de hueso al cogerla por primera vez#{{BoneHeart}} Los aumentos de vida dan corazones de hueso en lugar de contenedores" },
  { "t", "⟨t:Fiendish Amethyst⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera 4 Esbirros de Fiend de amatista al entrar en una sala sin limpiar" },
  { "t", "⟨t:Sturdy Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{SoulHeart}} +1 corazón de alma al entrar en un piso nuevo" },
  { "t", "⟨t:Brick Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Al cogerla, Isaac puede disparar una lágrima ladrillo de 15 de daño#Isaac puede recogerla tras dispararla y volver a lanzarla" },
  { "t", "⟨t:Sapphic Sapphire⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Charm}} Encanta a los enemigos femeninos#{{Freezing}} 8% de probabilidad de disparar lágrimas que ralentizan y congelan#{{Luck}} 33% de probabilidad con 8 de suerte" },
  { "t", "⟨t:Blood Diamond⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera un charco de sangre cuando Isaac recibe daño#{{BleedingOut}} 10% de probabilidad de disparar lágrimas que causan sangrado#{{Luck}} 40% de probabilidad con 8 de suerte" },
  { "t", "⟨t:Scented Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Charm}} Encanta a los enemigos en un radio corto alrededor de Isaac" },
  { "t", "⟨t:Arcade Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Slotmachine}} 25% de probabilidad de que las máquinas tragaperras sean gratis#{{Luck}} 66% de probabilidad con 17 de suerte" },
  { "t", "⟨t:Tinted Heart⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Heart}} 20% de probabilidad de soltar un corazón rojo al recibir daño#Al recibir daño explosivo, 35% de probabilidad de soltar:#{{SoulHeart}} Corazón de alma#{{Bomb}} Bomba#{{Key}} Llave#{{Chest}} Cofre" },
  { "t", "⟨t:Rose Quartz⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Recibir daño da un escudo temporal de 6 segundos que bloquea un proyectil#Recibir daño por contacto renueva la duración" },
  { "t", "⟨t:Hailstone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Slow}} Los enemigos cercanos a Isaac se ralentizan#{{Freezing}} Los enemigos en un radio corto de Isaac se congelan al morir" },
  { "t", "⟨t:Ramblin' Opal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Charm}} Genera Esporas shiitake aliadas en las salas sin limpiar, con un máximo de 3 a la vez" },
  { "t", "⟨t:Sand Dollar⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Coin}} Soltar la baratija en una {{Shop}} tienda la cambia por 10-20 monedas" },
  { "t", "⟨t:Henge Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Trinket}} Aumenta un 30% el poder de las baratijas de roca que lleves" },
  { "t", "⟨t:Salt Lamp⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Repele enemigos y proyectiles cercanos, pero pierde poder poco a poco#{{Battery}} Se puede recargar con baterías#Se recarga en cada piso nuevo" },
  { "t", "⟨t:Molten Slag⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Burning}} 2% de probabilidad de quemar a los enemigos cercanos en cada fotograma#{{ffGrind}} {{ColorTransform}}Efecto al moler#Al molerla en la Máquina minera, funde la otra baratija que lleves" },
  { "t", "⟨t:Thunder Egg⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↓ -0.1 Velocidad#En cada sala hay un 6% de probabilidad de que el Huevo de trueno se abra y dé una roca de mayor calidad#La probabilidad aumenta en cada sala, hasta un 50%" },
  { "t", "⟨t:Unobtainium⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Totalmente imposible de conseguir, ¡ni lo intentes!" },
  { "t", "⟨t:Sandstone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Confusion}} 20% de probabilidad de disparar una roca que confunde e inflige x4 de daño, pero encoge con el tiempo#{{Luck}} 100% de probabilidad con 27 de suerte#{{Trinket⟨t:Pocket Sand⟩}} Se convierte en Arena de bolsillo al recibir daño explosivo" },
  { "t", "⟨t:Fake Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Key}} Genera una llave al cogerla#Si hay una puerta cerrada con llave en la sala, la primera roca rota suelta una llave" },
  { "t", "⟨t:Citrine Pulp⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#20% de probabilidad de disparar una salpicadura de lágrimas de corto alcance#{{Luck}} 50% de probabilidad con 15 de suerte#Con enemigos cerca, pequeña probabilidad de crear un charco" },
  { "t", "⟨t:Bloodstone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.2 Daño por cada enemigo muerto en la sala#↑ +1 Daño al recibir daño#Los bonus de daño se desvanecen con el tiempo" },
  { "t", "⟨t:Emetic Antimony⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Collectible149}} Isaac puede disparar un tiro de Ipecac cada 15 segundos" },
  { "t", "⟨t:Double Rubble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{ffGrind}} {{ColorTransform}}Efecto al moler#Moler esta roca en la Máquina minera da dos rocas comunes o raras" },
  { "t", "⟨t:Rock from an Abyss⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#20% de probabilidad de aplicar Condena a 3 enemigos al empezar la sala#{{Luck}} 100% de probabilidad con 27 de suerte#{{ffDoom}}  Los enemigos condenados tienen un contador que baja cada vez que reciben daño#{{ffDoom}}  Al llegar a cero, el enemigo recibe una gran cantidad de daño" },
  { "t", "⟨t:Hector⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +1 Daño#↑ +0.27 Lágrimas#↓ -0.1 Velocidad#Se suelta a la fuerza al recibir daño" },
  { "t", "⟨t:Vessel Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{EmptyHeart}} Guarda un corazón extra#{{DevilChance}} No cuenta en contra de la probabilidad de trato con el diablo#Se rompe si recibes daño estando vacía" },
  { "t", "⟨t:Half Vessel Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{HalfHeart}} Guarda un corazón extra#{{DevilChance}} No cuenta en contra de la probabilidad de trato con el diablo#Se rompe si recibes daño estando vacía" },
  { "t", "⟨t:Full Vessel Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Heart}} Guarda un corazón extra#{{DevilChance}} No cuenta en contra de la probabilidad de trato con el diablo#Se rompe si recibes daño estando vacía" },
  { "t", "⟨t:Constant Rock Shooter⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.8 Lágrimas#Isaac nunca deja de disparar" },
  { "t", "⟨t:Robot Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Da a Isaac 2 láseres giratorios de corto alcance que causan efectos de estado aleatorios" },
  { "t", "⟨t:Rock Candy⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#15% de probabilidad de disparar una lágrima de cristal que encanta e inflige x1.5 de daño#{{Luck}} 100% de probabilidad con 27 de suerte#{{HalfHeart}} Los enemigos tienen un 15% de probabilidad de soltar al morir medio corazón rojo rosa que desaparece a los 2 segundos#{{Luck}} 40% de probabilidad con 25 de suerte" },
  { "t", "⟨t:Keystone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Key}} Cada vez que Isaac usa una llave:#↑ +0.1 Velocidad#↑ +0.1 Lágrimas#Las estadísticas desaparecen al entrar en un piso nuevo" },
  { "t", "⟨t:Silver Tongue⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{ffGrind}} La Máquina minera cuesta 1 céntimo menos" },
  { "t", "⟨t:Meat Slab⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Isaac suda sin parar lágrimas en arco#{{Heart}} El sudor aumenta cuanto menos vida tenga Isaac" },
  { "t", "⟨t:Sheep Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#7% de probabilidad de disparar una lágrima que frena y adormece#{{Luck}} 100% de probabilidad con 47 de suerte#{{ffSleeping}}  Los enemigos adormecidos se ralentizan y acaban durmiéndose#{{ffSleeping}}  Los enemigos dormidos reciben el doble de daño" },
  { "t", "⟨t:Rebellion Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Recibir daño aparta a los enemigos cercanos e inflige 2x el daño de Isaac#Los enemigos apartados también quedan magullados#{{ffBruise}}  Los enemigos magullados reciben daño extra por cada acumulación" },
  { "t", "⟨t:Dad's Legendary Golden Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{ffGrind}} {{ColorTransform}}Efecto al moler#Al molerla en la Máquina minera siempre genera una baratija dorada rara o mejor" },
  { "t", "⟨t:Bedrock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#33% de probabilidad de que aparezca una cama al empezar cada piso" },
  { "t", "⟨t:Sheetrock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Heart}} Cura 2 corazones al empezar cada piso#{{SoulHeart}} Dormir en una cama da 2 corazones de alma extra" },
  { "t", "⟨t:Fetal Stone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera un familiar bebé Golem#Inflige 5 de daño por lágrima#{{Confusion}} Estas lágrimas tienen más retroceso y un 20% de probabilidad de confundir" },
  { "t", "⟨t:Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara lágrimas a los enemigos cercanos#Las lágrimas infligen el daño de Isaac#Sigue disparando aunque esté en el suelo" },
  { "t", "⟨t:Vomit Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara potentes tiros explosivos a los enemigos cercanos que infligen 10 + el daño de Isaac#Sigue disparando aunque esté en el suelo#Los tiros explosivos no dañan a Isaac" },
  { "t", "⟨t:Wetstone Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera de forma pasiva pequeñas burbujas que bloquean proyectiles#Las burbujas infligen 2.62 de daño#Sigue soltando burbujas aunque esté en el suelo" },
  { "t", "⟨t:Constant Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara sin parar lágrimas en una dirección cardinal aleatoria que infligen el daño de Isaac#Sigue disparando aunque esté en el suelo" },
  { "t", "⟨t:Broken Gaping Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Atrae a todos los enemigos hacia Isaac cada 2 segundos#Sigue atrayendo aunque esté en el suelo" },
  { "t", "⟨t:Brimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara cada cierto tiempo rayos de azufre en una dirección cardinal aleatoria que infligen 0.66x el daño de Isaac#Sigue disparando rayos aunque esté en el suelo" },
  { "t", "⟨t:Cross Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara sin parar lágrimas en forma de + y x que infligen el daño de Isaac#Sigue disparando aunque esté en el suelo" },
  { "t", "⟨t:Eye Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara sin parar un láser giratorio que inflige 0.66x el daño de Isaac#Sigue disparando láseres aunque esté en el suelo" },
  { "t", "⟨t:Cauldron Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Charm}} Genera una copia aliada de un enemigo de la sala#Las copias desaparecen al salir de la sala#Sigue generando copias aunque esté en el suelo" },
  { "t", "⟨t:Gaping Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Atrae los recolectables sin parar#Sigue atrayendo recolectables aunque esté en el suelo" },
  { "t", "⟨t:Trimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara un triple disparo a los enemigos cercanos que inflige el daño de Isaac#Sigue disparando aunque esté en el suelo" },
  { "t", "⟨t:Sensory Grimlin⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Caminar en una dirección hace que la gárgola dispare hacia allí#Las lágrimas escalan con el daño de Isaac#Sigue disparando aunque esté en el suelo" },
  { "t", "⟨t:Focus Crystal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Los enemigos a menos de {{ColorYellow}} 2.5 casillas {{ColorWhite}}reciben un{{ColorYellow}} 20%{{ColorWhite}} más de daño {{ColorGray}}(+20% por acumulación)" },
  { "t", "⟨t:Oddly Smooth Stone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Empiezas cada combate con {{ColorCyan}}1{{CR}} de {{ColorYellow}}Destreza{{CR}}#{{Heart}} Todos los corazones rojos curan medio corazón adicional" },
  { "t", "⟨t:Moonstone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Al entrar en cualquier tipo de {{SecretRoom}} sala secreta, Isaac gana al azar uno de estos:#↑ +0.3 Lágrimas#↑ +0.38 Alcance#↑ +0.3 Velocidad de tiro#↑ +1 Suerte" },
  { "t", "⟨t:Limestone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Deja un rastro de charco de lima que inflige 0.5x el daño de Isaac#Encanta para siempre a los enemigos relacionados con cítricos#33% de probabilidad de que los enemigos Sourpatch se sustituyan por Limepatches" },
  { "t", "⟨t:Carnal Carnelian⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ Ganas daño y velocidad cuanto más cerca esté Isaac de los enemigos" },
  { "t", "⟨t:Rebar Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Heart}} 25% de probabilidad de bloquear el daño a corazones rojos#{{HalfHeart}} El daño a corazones rojos es siempre de medio corazón" },
  { "t", "⟨t:Dogrock Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↓ -100 Suerte#Distorsiona la pantalla y la música#{{Slow}} Ralentiza a los enemigos en un radio pequeño alrededor de Golem" },
  { "t", "⟨t:Stalactite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Las explosiones hacen caer rocas del techo#Las rocas del techo infligen 2x el daño de Isaac#Evita el daño de los proyectiles que caen" },
  { "t", "⟨t:Cast Gem⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Otorga una gema teledirigida que se lanza al atacar, se pega a los enemigos y los daña y magulla#{{ffBruise}}  Los enemigos magullados reciben daño extra por cada acumulación" },
  { "t", "⟨t:Shard of Golgotha⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Collectible722}} Encadena 7 segundos al enemigo con más vida al empezar cada sala#Los enemigos encadenados no pueden moverse ni atacar" },
  { "t", "⟨t:Smoky Quartz⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Timer}} Recibir daño da un aumento temporal de velocidad y confunde a los enemigos cercanos durante 7 segundos" },
  { "t", "⟨t:Twinkling Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{ffGrind}} {{ColorTransform}}Efecto al moler#Moler esta roca en la Máquina minera da una geoda común o rara" },
  { "t", "⟨t:Rock Cake⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{ffGrind}} {{ColorTransform}}Efecto al moler#Moler otras rocas en la Máquina minera cura medio corazón rojo" },
  { "t", "⟨t:Charcoal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#15% de probabilidad de disparar una lágrima muy lenta que inflige más daño cuanto más lejos llega#{{Luck}} 50% de probabilidad con 43 de suerte" },
  { "t", "⟨t:Knife Pebble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +1 Daño" },
  { "t", "⟨t:Teardrop Pebble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.4 Lágrimas" },
  { "t", "⟨t:Arrow Pebble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +1.25 Alcance#↑ +0.2 Velocidad de tiro" },
  { "t", "⟨t:Clover Pebble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +2 Suerte" },
  { "t", "⟨t:Shoe Pebble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.3 Velocidad" },
  { "t", "⟨t:Fruity Pebble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.15 Velocidad#↑ +0.15 Lágrimas#↑ +0.3 Daño#↑ +0.75 Alcance#↑ +0.18 Velocidad de tiro#↑ +1 Suerte" },
  { "t", "⟨t:Mixed Pebble⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.15 Velocidad#↑ +0.5 Daño" },
  { "t", "⟨t: Mixed Pebble ⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.15 Velocidad#↑ +1 Suerte" },
  { "t", "⟨t:  Mixed Pebble  ⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.15 Lágrimas#↑ +1 Suerte" },
  { "t", "⟨t:   Mixed Pebble   ⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.75 Alcance#↑ +0.5 Daño" },
  { "t", "⟨t:    Mixed Pebble    ⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.75 Alcance#↑ +1 Suerte" },
  { "t", "⟨t:     Mixed Pebble     ⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.15 Velocidad#↑ +0.75 Alcance" },
  { "t", "⟨t:Achilles' Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Los enemigos obtienen un punto débil aleatorio orientado hacia una dirección aleatoria#Si se les daña desde esa dirección, reciben x1.5 de daño" },
  { "t", "⟨t:Electrum⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Usar un objeto activo electrocuta a los enemigos cercanos#El daño escala con la cantidad de carga y el daño de Isaac#Los efectos varían según el objeto activo de Isaac" },
  { "t", "⟨t:Pure Quartz⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{SoulHeart}} Si Isaac pierde todos sus corazones de alma:#{{Collectible313}} Obtiene un escudo de Manto sagrado#{{Timer}} Se vuelve invencible durante 10 segundos" },
  { "t", "⟨t:Amazonite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#La primera compra en una {{Shop}} tienda tiene un gran descuento#Tras comprar un objeto, desaparece y aparece en el siguiente piso" },
  { "t", "⟨t:Star Sapphire⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera un familiar orbital tambaleante que apunta al enemigo o proyectil más cercano#Bloquea disparos e inflige 0.5x el daño de Isaac" },
  { "t", "⟨t:Gravestone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Recibir daño genera uno de estos:#{{Collectible634}} Un fantasma teledirigido que explota#{{Collectible684}} Un fantasma que persigue a los enemigos, inflige daño por contacto y explota a los 3 segundos#15% de probabilidad de que aparezca cualquiera de los fantasmas al destruir rocas" },
  { "t", "⟨t:Sand Castle⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Trinket⟨t:Pocket Sand⟩}} Anula 3 golpes antes de convertirse en Arena de bolsillo" },
  { "t", "⟨t:Damaged Sand Castle⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Trinket⟨t:Pocket Sand⟩}} Anula 2 golpes antes de convertirse en Arena de bolsillo" },
  { "t", "⟨t:Broken Sand Castle⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Trinket⟨t:Pocket Sand⟩}} Anula 1 golpe antes de convertirse en Arena de bolsillo" },
  { "t", "⟨t:Guarded Garnet⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#30% de probabilidad de obtener al recibir daño un escudo que dura una sala y bloquea un golpe#{{Luck}} 100% de probabilidad con 35 de suerte#Los enemigos salen despedidos al romperse el escudo" },
  { "t", "⟨t:Shamrock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +5 Suerte#↓ Al recibir daño, Isaac pierde 1 de suerte durante el piso" },
  { "t", "⟨t:Gas Pocket⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Poison}} Las rocas tienen un 10% de probabilidad de soltar gas venenoso cada 4 segundos#35% de probabilidad de que las rocas suelten grandes nubes de gas venenoso al romperse#{{Luck}} 100% de probabilidad con 65 de suerte#El gas venenoso no daña a Isaac" },
  { "t", "⟨t:Soap Stone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Elimina todos los proyectiles al limpiar la sala y al recibir daño#Genera 3 burbujas al recibir daño" },
  { "t", "⟨t:Spirit Urn⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera 3 fuegos fatuos al entrar en una sala de {{BossRoom}} jefe o de {{MiniBoss}} minijefe#Genera 3 fuegos fatuos al empezar una {{ChallengeRoom}} sala de desafío" },
  { "t", "⟨t:Sun Shard⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera en cada sala un órgano orbital aleatorio que inflige 0.5x el daño de Isaac y bloquea disparos#Los órganos tienen efectos especiales al recibir proyectiles" },
  { "t", "⟨t:Steadfast Stone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Al recibir daño mortal, Isaac tritura otra baratija de roca que lleve para evitar la muerte#También genera un corazón de alma" },
  { "t", "⟨t:Rai Stone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Coin}} 15% de probabilidad de que los enemigos suelten una moneda de piedra al morir#Las monedas de piedra desaparecen a los 2.5 segundos" },
  { "t", "⟨t:Ore Penny⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Coin}} Coger una moneda tiene un 50% de probabilidad de sumar otra moneda al contador#3% de probabilidad de convertir las rocas normales en rocas de oro falso" },
  { "t", "⟨t:Heavy Metal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↓ -0.15 Velocidad#Da daño y probabilidad de evitar daño según lo lento que vaya Isaac" },
  { "t", "⟨t:Grossular⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Lanza cada cierto tiempo un pulso que {{Fear}} asusta, {{Poison}} envenena o {{Confusion}} confunde a los enemigos cercanos" },
  { "t", "⟨t:Sulfur Crystal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Timer}} {{Collectible118}} Otorga Azufre al empezar cada 4ª sala" },
  { "t", "⟨t:A Bit of Trollite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Un poquito de troleo" },
  { "t", "⟨t:Throwlomite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Cada 1.67 segundos lanza una piedra a un enemigo cercano que escala con el daño de Isaac" },
  { "t", "⟨t:Hearthstone⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Activa un efecto beneficioso aleatorio cada vez que se usa una carta" },
  { "t", "⟨t:Magnetic Sand⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.45 Lágrimas#↓ -0.35 Daño#{{Magnetize}} 10% de probabilidad de disparar lágrimas magnéticas#{{Luck}} 50% de probabilidad con 20 de suerte" },
  { "t", "⟨t:Insatiable Apatite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ Aumento temporal de daño al coger corazones#{{Heart}} Los corazones se pueden consumir con la vida llena para aumentar el daño#Algunos tipos de corazón tienen efectos extra al consumirse" },
  { "t", "⟨t:Power Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Battery}} Romper rocas tiene un 5% de probabilidad de añadir 1 carga al objeto activo#{{Luck}} 25% de probabilidad con 20 de suerte" },
  { "t", "⟨t:Tiger's Eye⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera un familiar ojo que rebota por la sala, inflige daño por contacto y bloquea disparos#El ojo rebota hacia los enemigos más cercanos#Inflige 0.66x el daño de Isaac" },
  { "t", "⟨t:Smaller Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Cada vez que se destruye una roca tintada:#↑ +0.33 Daño#↓ -0.06 Velocidad" },
  { "t", "⟨t:Nitro Crystal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Coin}} Coger monedas da a Isaac un aumento de lágrimas y velocidad" },
  { "t", "⟨t:Shard of Golem⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Curarte de más carga una barra de vida secundaria#{{Damage}} Llenar esta barra acumula un aumento de hasta +1.8 de daño por cada corazón llenado#Cuando se llenan todos los corazones, se funden todas las baratijas que lleves#Esta barra de vida se ve al abrir el mapa" },
  { "t", "⟨t:Rock Worm⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.4 Lágrimas#↑ +0.4 Daño#Otorga durante el piso el efecto de una baratija gusano aleatoria al empezarlo" },
  { "t", "⟨t:Fool's Unobtainium⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Supuestamente imposible de conseguir, pero no cuesta tanto" },
  { "t", "⟨t:Minichibisidian⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#10% de probabilidad cada 3 segundos de transformar a un enemigo de la sala en un Bony" },
  { "t", "⟨t:Friendly Rapid Fire Opal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Obtienes un fusil de asalto con munición limitada al entrar en una sala que tiene:#↑ 0.5x multiplicador de cadencia#↑ +6.25 Alcance#↑ +1.0 Velocidad de tiro#Lágrimas perforantes" },
  { "t", "⟨t:Hiddenite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Confusion}} Entrar y luego salir de la línea de visión de un enemigo por primera vez lo confunde 2.67 segundos" },
  { "t", "⟨t:Pocket Rock-it⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#10% de probabilidad de disparar una lágrima cohete que persigue a los enemigos#{{Luck}} 25% de probabilidad con 10 de suerte#Los cohetes disparan lágrimas de poco daño cerca de los enemigos#Los cohetes estallan en un patrón de lágrimas al impactar, según su color" },
  { "t", "⟨t:Wormhole Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera dos agujeros de gusano#Las lágrimas y proyectiles que entran en un portal salen por el otro#Las lágrimas disparadas a través de portales apuntan a los enemigos y tienen efectos extra#Los agujeros de gusano estallan en lágrimas de vez en cuando y cambian de posición" },
  { "t", "⟨t:Atlas' Burden⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↓ -0.15 Velocidad#25% de probabilidad de que caiga una roca sobre los enemigos#{{Luck}} 50% de probabilidad con 3 de suerte#{{Slow}} La roca ralentiza a los enemigos y puede matar al instante con el tiempo a los que no son jefes" },
  { "t", "⟨t:Arachnite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Las arañas azules se sustituyen por arañas de roca aliadas#Pueden ser arañas de roca tintada o de carbón" },
  { "t", "⟨t:Homoerotic Ruby⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#15% de probabilidad de disparar lágrimas en llamas que queman#{{Luck}} 50% de probabilidad con 35 de suerte#Los enemigos femeninos tienen un 10% de probabilidad de enfurecerse al azar#{{ffBerserk}}  Los enemigos enfurecidos cambian de objetivo, infligen daño extra, se mueven más rápido y no pueden morir" },
  { "t", "⟨t:Gay Garnet⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Charm}} Encanta a los enemigos femeninos#{{Collectible⟨c:Peppermint⟩}} 20% de probabilidad de disparar un fuego que daña y congela a los enemigos#{{Luck}} 50% de probabilidad con 30 de suerte#Los enemigos femeninos tienen un 15% de probabilidad de enfurecerse al azar#{{ffBerserk}}  Los enemigos enfurecidos cambian de objetivo, infligen daño extra, se mueven más rápido y no pueden morir" },
  { "t", "⟨t:Lithopedion⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera un familiar Gaper de piedra que empuja a los enemigos y bloquea disparos" },
  { "t", "⟨t:Jesus Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +1 vida#{{Heart}} Al morir, Isaac reaparece en la sala actual con 6 corazones añadidos a su barra de vida" },
  { "t", "⟨t:Lost Artifact⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Al limpiar la sala aparecen 1-3 moscas hada#Las moscas hada infligen daño por contacto a los enemigos y mueren al cabo de un rato#Las moscas hada tienen tres tamaños distintos, cada uno con efectos diferentes#Los nombres de las moscas hada se ven al abrir el mapa" },
  { "t", "⟨t:Ridiculous Metal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Al entrar en una sala con enemigos, Isaac juega un minijuego de ritmo#Disparar lágrimas a tiempo daña a todos los enemigos de la sala#{{Damage}} Cuantas más notas aciertes, más daño hace" },
  { "t", "⟨t:Top Rock⟩", nil, "↑ +0.2 Velocidad#↑ +0.14 Lágrimas#↑ +0.5 Daño#↑ +1.25 Alcance#↑ +0.5 Velocidad de tiro#↑ +2 Suerte#↓ Impide que suban las estadísticas mientras la llevas" },
  { "t", "⟨t:Chunk of Gallium⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#15% de probabilidad de disparar una lágrima gris que deja un rastro de charco ralentizador#{{Luck}} 45% de probabilidad con 20 de suerte" },
  { "t", "⟨t:Onion Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Genera familiares Brickmin que se pueden apuntar y lanzar cuando están cerca#Hay 3 Brickmin distintos con efectos y comportamientos diferentes#Ganas un Brickmin cada 4 salas limpiadas" },
  { "t", "⟨t:Paperweight⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Permite abrir cofres a golpes sin pagar nada#{{Trinket⟨t:Pocket Sand⟩}} 10% de probabilidad de romperse en Arena de bolsillo tras 5 usos" },
  { "t", "⟨t:Shroomite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Dispara cada cierto tiempo lágrimas onduladas a enemigos aleatorios#{{Confusion}} 20% de probabilidad de que estas lágrimas confundan" },
  { "t", "⟨t:Azerite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{ffGrind}} {{ColorTransform}}Efecto al moler#Moler otras rocas que lleves en la Máquina minera da una pequeña mejora de estadísticas#Isaac puede recibir mejoras hasta 20 veces" },
  { "t", "⟨t:Gravel⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{ffGrind}} {{ColorTransform}}Efecto al moler#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Moler o triturar otras rocas que lleves da un ataque de lluvia de rocas#El ataque de lluvia de rocas se acumula con cada roca triturada o molida#La lluvia de rocas se reinicia en cada piso" },
  { "t", "⟨t:Pig Iron⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Coin}} Comprar un objeto en la tienda te devuelve el 25% de su coste" },
  { "t", "⟨t:Rocky⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#En una sala sin limpiar, 0.3% de probabilidad en cada tic de que brille un enemigo aleatorio#{{Damage}} Mientras miras a un enemigo brillante:#↑ x1.5 Daño#↑ x0.85 Cadencia#↑ +3 Suerte" },
  { "t", "⟨t:Fulgurite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Collectible494}} 20% de probabilidad de disparar lágrimas eléctricas que sueltan una chispa al impactar#{{Luck}} 50% de probabilidad con 25 de suerte#{{ffGrind}} {{ColorTransform}}Efecto al moler#Moler esta roca en la Máquina minera sobrecarga todos los activos que lleves" },
  { "t", "⟨t:Furnace Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Collectible289}} 6% de probabilidad de disparar un fuego rojo que bloquea disparos enemigos e inflige daño por contacto#{{Luck}} 50% de probabilidad con 16 de suerte" },
  { "t", "⟨t:Malachite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Los enemigos campeones reciben 1.5x de daño" },
  { "t", "⟨t:Onyx⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{BlackHeart}} 60% de probabilidad de que los corazones de alma se vuelvan corazones negros#{{SoulHeart}} 20% de probabilidad de que los corazones rojos se vuelvan corazones de alma#!!! Los corazones rojos desaparecen si no se convierten" },
  { "t", "⟨t:Fish Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#35% de probabilidad de generar una mosca azul al romper una roca#35% de probabilidad de duplicar cualquier mosca azul generada" },
  { "t", "⟨t:Hellvite⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.02 Daño cada vez que Isaac mata a un enemigo#Recibir daño hace desaparecer la roca#Fundir la roca evita que desaparezca, pero también que siga ganando daño" },
  { "t", "⟨t:Booster Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ Da una mejora de estadística aleatoria en cada sala" },
  { "t", "⟨t:Rockette Dragoon⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Chargeable}} Obtienes un ataque cargado que dispara 2 balas al enemigo más cercano" },
  { "t", "⟨t:Eternal Crystal⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Mientras Isaac tenga un corazón eterno:#↑ +1 Daño#↑ +0.5 Lágrimas#{{EternalHeart}} Genera un corazón eterno al empezar cada dos pisos" },
  { "t", "⟨t:Triangular Gem⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Cada 3º golpe a un enemigo, 33% de probabilidad de generar 3 lágrimas giratorias a su alrededor que infligen 1.33x el daño de Isaac" },
  { "t", "⟨t:Quicksilver⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{Timer}} Al entrar en una sala, durante los primeros 4 segundos Isaac tiene:#↑ +0.55 Lágrimas#↑ +2 Velocidad" },
  { "t", "⟨t:Non-Euclidean Rock⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#{{CurseMazeSmall}} Garantiza la Maldición del laberinto en el siguiente piso#Cuando la Maldición del laberinto mueve a Isaac, gana:#↑ +0.4 Daño durante el piso#↑ +0.4 Lágrimas durante la sala#{{Damage}} El bonus de daño se multiplica por 2 durante la sala#Una moneda, bomba, llave o medio corazón rojo si Isaac puede curarse" },
  { "t", "⟨t:Mirror Slate⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Inflige 40 de daño a todos los enemigos al soltarla#Tiene un 66% de probabilidad de romperse al soltarla y generar un corazón negro" },
  { "t", "⟨t:Hammer Head⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +0.3 Daño durante la sala al destruir una roca#Las rocas se rompen en lágrimas de roca de corto alcance al destruirse" },
  { "t", "⟨t:Uranium⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Recibir daño tiene un 25% de probabilidad de soltar un corazón temporal#{{ffRadiation}} Más resistencia a la radiación" },
  { "t", "⟨t:Sacred Soil⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#Soltar la baratija crea un aura blanca#Dentro del aura:#↑ x2.5 multiplicador de cadencia#↑ x1.2 multiplicador de daño#Lágrimas teledirigidas#Probabilidad de bloquear daño#{{ffGrind}} {{ColorTransform}}Efecto al moler#Al molerla en la Máquina minera siempre genera una baratija rara" },
  { "t", "⟨t:Ancient Effigy⟩", nil, "{{ffRock}} {{ColorTransform}}Baratija de roca (Roca)#↑ +1 Daño#{{Speed}} Se funde sola si Isaac tiene 1.6 de velocidad o más#Ignora las penalizaciones por fundir" },
  { "t", "⟨t:Breakfast Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{ColorTransform}}{{ffCrush}} Efecto al triturar#↑ +1 vida al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Sack Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{GrabBag}} 10% de probabilidad de que los recolectables aleatorios se vuelvan sacos#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{GrabBag}} Genera un saco al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Coprolite Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Genera 1 mosca azul por cada sala nueva en la que entras#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Genera 12 moscas azules al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Beeter Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Cada lágrima disparada lanza otra más débil que se reparte alrededor de Isaac#Esta lágrima inflige 0.3x el daño de Isaac#Las lágrimas extra salen girando en sentido horario cada vez que Isaac dispara#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Charm}} Genera un enemigo Beeter aliado al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Fly Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Genera una Langosta del hambre por cada sala nueva en la que entras#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da una Mosca bonita al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:GMO Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Pill}} Isaac se ve obligado a tomar 2 píldoras aleatorias tras vencer a un jefe#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Pill}} Toma 3 píldoras aleatorias al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Sword Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#↑ +1 Daño#↑ +0.27 Lágrimas#↑ +0.75 Alcance#↑ +0.20 Velocidad de tiro#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Al triturarla el Mendigo de bismuto, ganas para siempre el 50% de las estadísticas del Fósil espada" },
  { "t", "⟨t:Fortune Worm Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#↑ +0.2 Velocidad de tiro#↑ +2 Suerte#1% de probabilidad de disparar una lágrima gusano de la fortuna que inflige x1.05 de daño#{{Luck}} 33% de probabilidad con 18 de suerte#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{SoulHeart}} Genera un corazón de alma extra y muestra 3 predicciones aleatorias al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Primordial Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Collectible317}} 7% de probabilidad de disparar una pequeña ráfaga de lágrimas de Líquido misterioso#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da las rocas iniciales de Golem al triturarla ({{Trinket⟨t:Dirt Clump⟩}} + {{Trinket⟨t:Rolling Rock⟩}}) el Mendigo de bismuto" },
  { "t", "⟨t:Rerolligan Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#10% de probabilidad de disparar una lágrima dado que cambia a los enemigos#{{Luck}} 40% de probabilidad con 8 de suerte#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Genera 3 Dados de cristal aleatorios al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Fossilized Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Los efectos al triturar fósiles se activan dos veces#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Activa el efecto de otro fósil que lleves al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Fish Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Recibir daño genera de 1 a 4 moscas azules#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Charm}} Genera un Portal aliado al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Runic Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Rune}} Las runas son más comunes#Usar runas o piedras del alma suelta un fragmento de runa#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Suelta 4 fragmentos de runa al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Canned Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Isaac suelta un pedo aleatorio al recibir daño#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Charm}} Genera un bicho Litter encantado al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Balanced Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#50% de probabilidad de que la recompensa de la sala sea un recolectable del que Isaac no tenga ninguno#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da 3 del recolectable que menos tengas al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Buried Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Cada piso tiene un punto marcado que se puede volar para generar un fósil#Los montículos de tierra se pueden abrir con bombas#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da un fósil aleatorio al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Trippy Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Collectible398}} 13% de probabilidad de disparar lágrimas que encogen a los enemigos#{{Luck}} 100% de probabilidad con 44 de suerte#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Encoge a Isaac al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Max's Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Collectible445}} Un lobo aúlla en las salas adyacentes a una sala secreta o supersecreta#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Al triturarla el Mendigo de bismuto, se revela la próxima roca tintada que encuentre Isaac" },
  { "t", "⟨t:Bomb Sack Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Bomb}} Las bombas crean un anillo de ondas de roca#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Bomb}} Genera 3 bombas al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Death Cap Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#↓ Pequeña bajada de estadísticas por cada sala limpiada#{{ColorTransform}}{{ffCrush}} Efecto al triturar#↑ Aumenta todas las estadísticas al triturarla el Mendigo de bismuto#↑ Las mejoras son proporcionales a las salas limpiadas, hasta 30 salas" },
  { "t", "⟨t:Explosive Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Bomb}} 13% de probabilidad de soltar una bomba extra al limpiar la sala#20% de probabilidad de que las rocas se sustituyan por rocas bomba#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Collectible483}} Al triturarla el Mendigo de bismuto, las 3 próximas salas sin limpiar sufren una explosión de Mama Mega" },
  { "t", "⟨t:Colossal Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#↑ Duplica el tamaño de las lágrimas#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Activa 3 efectos de fósil aleatorios al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Skuzz Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Genera de 2 a 3 skuzzes morados cada vez que entras en una sala activa#{{Slow}} Este skuzz inflige 3x el daño de Isaac y ralentiza a los enemigos#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Genera de 5 a 7 skuzzes azules al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Fossilized Blessing⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#↑ +0.4 Lágrimas#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da una baratija de roca aleatoria al empezar la siguiente partida al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Petrified Sock⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#10% de probabilidad de disparar lágrimas que petrifican#{{Luck}} 100% de probabilidad con 45 de suerte#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da un bebé familiar aleatorio al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Molten Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#↑ Mejora un 15% la eficacia de las baratijas de roca fundidas#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da y funde una roca común aleatoria al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Value Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Coin}} Los objetos de la tienda cuestan un céntimo menos#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Coin}} Genera 3 monedas al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Coral Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#25% de probabilidad de disparar 4 lágrimas en forma de X#{{Luck}} 100% de probabilidad con 75 de suerte#{{Heart}} Cura 1 corazón rojo al cogerla#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Charm}} Genera 3 cargadores ahogados aliados y cura un corazón al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Necromantic Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#20% de generar un hueso orbital al matar a un enemigo#{{Luck}} 40% de probabilidad con 20 de suerte#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Da un fósil ya triturado en esta partida al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Brain Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#Las lágrimas son teledirigidas durante un momento al dispararlas#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Card}} Genera una carta del Mago al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Refund Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Trinket⟨t:Pocket Sand⟩}} Triturar otros fósiles en el Mendigo de bismuto genera Arena de bolsillo#{{ffGrind}} {{ColorTransform}}Efecto al moler#Con este fósil, la Arena de bolsillo se puede moler gratis en la Máquina minera#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Genera 2 Arenas de bolsillo al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:The Left Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{RedChest}} Convierte todos los cofres en cofres rojos#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{RedChest}} Genera un cofre rojo al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Thank-You Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Beggar}} Los mendigos dan sus recompensas dos veces#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Card}} Genera una carta del Juicio al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Hollow Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#↑ +1.35 Daño#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Garantiza una sala del diablo/ángel y genera un corazón negro al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Elephant Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{EmptyBoneHeart}} Los corazones de hueso aguantan un golpe más antes de romperse#Ese golpe se recupera cada vez que se llena el corazón de hueso#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{Charm}} Genera un Bony gigante aliado al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Golden Fossil⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{GoldenChest}} Sustituye todos los cofres por cofres dorados#{{ColorTransform}}{{ffCrush}} Efecto al triturar#{{GoldenChest}} Genera un cofre dorado al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Fossilized Coin⟩", nil, "{{ffFossil}} {{ColorTransform}}Baratija de roca (Fósil)#{{Coin}} 15% de probabilidad de mejorar las monedas a níqueles#7% de probabilidad de mejorarlas a monedas de diez#{{ColorTransform}}{{ffCrush}} Efecto al triturar#Genera un cofre tienda al triturarla el Mendigo de bismuto" },
  { "t", "⟨t:Curved Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +1 Daño#↑ +0.5 Daño extra si llevas otra Geoda" },
  { "t", "⟨t:Haunted Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#20% de probabilidad de disparar una lágrima espectral y perforante#{{Luck}} 100% de probabilidad con 40 de suerte#↑ Más probabilidad si llevas otra Geoda" },
  { "t", "⟨t:Health Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{Heart}} Cuando Isaac baja a 1 corazón rojo o menos, cura corazones rojos y se rompe#{{SoulHeart}} +1 corazón de alma al romperse la roca si llevas otra Geoda" },
  { "t", "⟨t:Little Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#Reduce el tamaño de Isaac#↑ Encoge más si llevas otra Geoda" },
  { "t", "⟨t:Quick Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ Sube la velocidad a 1.75 en las salas limpias#↑ +0.10 Velocidad extra si llevas otra Geoda" },
  { "t", "⟨t:Webby Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{Slow}} 20% de probabilidad de disparar lágrimas que ralentizan#{{Luck}} 100% de probabilidad con 40 de suerte#↑ Si llevas otra Geoda, los enemigos alcanzados por lágrimas ralentizadoras dejan un charco blanco ralentizador" },
  { "t", "⟨t:Lucky Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +1 Suerte#↑ +2 Suerte extra si llevas otra Geoda" },
  { "t", "⟨t:Phlegmy Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#10% de probabilidad de disparar una lágrima de moco pegajosa#{{Luck}} 100% de probabilidad con 90 de suerte#{{Slow}} Si llevas otra Geoda, las lágrimas de moco ralentizan a los enemigos" },
  { "t", "⟨t:Lob Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +1 Alcance#Las lágrimas se disparan ahora en arco#↑ +0.5 Alcance extra si llevas otra Geoda" },
  { "t", "⟨t:Sodalite Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#4% de probabilidad de disparar lágrimas críticas moradas que infligen x5 de daño#{{Luck}} 33% de probabilidad con 11 de suerte#↑ Más probabilidad si llevas otra Geoda" },
  { "t", "⟨t:Placebeode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#Si se funde, las Geodas ya no necesitan ocupar ambas ranuras de baratija" },
  { "t", "⟨t:Warm Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#Cerca de una chimenea:#↑ +4 Daño#↑ +0.2 Velocidad de tiro#Los suelos cálidos dan:#↑ +2 Daño#↑ +0.2 Velocidad de tiro#↑ Si llevas otra Geoda, +5 de daño extra y lágrimas de fuego junto a una chimenea" },
  { "t", "⟨t:Chain Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#Las rocas destruidas tienen un 40% de probabilidad de romper las rocas adyacentes#↑ La probabilidad sube al 70% si llevas otra Geoda#↑ Si llevas otra Geoda, los pozos junto a otras rocas también tienen un 20% de probabilidad de rellenarse" },
  { "t", "⟨t:Rusty Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +8 Daño#El daño se desvanece en 2 minutos y 13 segundos#↑ Si llevas otra Geoda, el daño baja más despacio" },
  { "t", "⟨t:Fragmented Onyx Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{Fear}} 10% de probabilidad de disparar lágrimas que asustan#{{Luck}} 100% de probabilidad con 26 de suerte#↑ Más probabilidad si llevas otra Geoda#{{DevilRoom}} Si llevas otra Geoda, los enemigos asustados reciben daño extra según la probabilidad de trato con el diablo" },
  { "t", "⟨t:Quantum Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#Isaac dispara 3 lágrimas a la vez#Cuando una lágrima golpea a un enemigo, las otras 2 desaparecen#↑ Si llevas otra Geoda, dos lágrimas pueden impactar en un enemigo" },
  { "t", "⟨t:Technological Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#Al disparar lanza un láser de corto alcance que inflige un 30% de daño#↑ Dispara 2 rayos si llevas otra Geoda" },
  { "t", "⟨t:Rubber Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#15% de probabilidad de disparar una lágrima pelota de tenis que rebota y magulla#{{Luck}} 50% de probabilidad con 18 de suerte#↑ Más probabilidad y retroceso si llevas otra Geoda#{{ffBruise}}  Los enemigos magullados reciben daño extra por cada acumulación" },
  { "t", "⟨t:Calzone Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#5% de probabilidad de disparar un gusano perforante que embiste hacia delante#{{Luck}} 50% de probabilidad con 9 de suerte#{{Bait}} El gusano marca a los enemigos#Los demás enemigos atacan a los enemigos marcados#↑ Más probabilidad de dispararlo si llevas otra Geoda" },
  { "t", "⟨t:Tough Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{ffCrush}} 20% de probabilidad de no destruir una geoda al triturarla el Mendigo de bismuto#↑ Más probabilidad si llevas otra Geoda" },
  { "t", "⟨t:Tipsy Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +2 Daño#Los movimientos de Isaac se vuelven erráticos#↑ Si llevas otra Geoda, +1.5 de daño extra y movimientos más intensos" },
  { "t", "⟨t:A-Side Vinyl Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +1 Daño#↑ +0.24 Velocidad de tiro#Pasa a la cara B en el primer piso de cada capítulo#↑ +0.07 de velocidad y +0.2 de lágrimas extra si llevas otra Geoda" },
  { "t", "⟨t:B-Side Vinyl Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +0.2 Velocidad#↑ +0.66 Lágrimas#Pasa a la cara A en el segundo piso de cada capítulo#↑ +0.3 de daño y +0.08 de velocidad de tiro extra si llevas otra Geoda" },
  { "t", "⟨t:Prismatic Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#12% de probabilidad de que los enemigos suelten Fragmentos de prisma al morir#↑ Los Fragmentos de prisma mejoran una estadística aleatoria durante 10 segundos#25% de probabilidad de que aparezca un Fragmento de prisma al limpiar la sala#↑ Si llevas otra geoda, las mejoras se duplican y duran más" },
  { "t", "⟨t:Fractal Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#15% de probabilidad de disparar un tiro en espiral que adormece#{{Luck}} 45% de probabilidad con 20 de suerte#↑ Si llevas otra Geoda, más probabilidad y un 33% de que los enemigos se duerman al instante#{{ffSleeping}}  Los enemigos adormecidos se ralentizan y acaban durmiéndose#{{ffSleeping}}  Los enemigos dormidos reciben el doble de daño" },
  { "t", "⟨t:GMO Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{Pill}} Tomar una píldora obliga a Isaac a tomar otra#↑ Si llevas otra Geoda, Isaac toma además una píldora positiva" },
  { "t", "⟨t:Swallowed Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{Coin}} Recibir daño genera 1 moneda#↑ Si llevas otra Geoda, 33% de probabilidad de generar una moneda doble" },
  { "t", "⟨t:Voodoo Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#↑ +1.5 Daño si hay una maldición en el piso#↑ +0.35 Daño durante el piso al entrar por primera vez en una sala de maldición#{{Damage}} Si llevas otra Geoda, el bonus de daño aumenta 1.5x" },
  { "t", "⟨t:Umbilical Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{HalfHeart}} Tener medio corazón rojo o menos otorga {{Collectible100}} Pequeño Steven#{{Collectible318}} Recibir daño tiene un 30% de probabilidad de generar un familiar Géminis durante la sala#{{Luck}} 100% de probabilidad con 35 de suerte#↑ Si llevas otra Geoda, mejora la probabilidad base de que aparezca Géminis#↑ Si llevas otra Geoda, Pequeño Steven puede aparecer con un corazón o menos" },
  { "t", "⟨t:AAA Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{Battery}} Los objetos activos necesitan 1 carga menos#↑ Si llevas otra Geoda, necesitan 2 cargas menos" },
  { "t", "⟨t:Liberty Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#25% de probabilidad de un efecto de seta aleatorio por sala#↑ Si llevas otra Geoda, más probabilidad de obtener un efecto de seta#↑ Si llevas otra Geoda, puedes obtener un efecto de seta adicional" },
  { "t", "⟨t:Nonagon Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{Battery}} 25% de probabilidad de generar una batería aleatoria al usar un objeto activo#↑ Más probabilidad si llevas otra Geoda" },
  { "t", "⟨t:Devouring Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#{{DevilRoom}} Permite a Isaac coger un trato con el diablo gratis#!!! Se destruye al coger uno#↑ Si llevas otra geoda, se consume esa en su lugar" },
  { "t", "⟨t:The Strongest Geode⟩", nil, "{{ffGeode}} {{ColorTransform}}Baratija de roca (Geoda)#Coger rocas raras o infernales las tritura y las convierte en una roca común#{{HalfSoulHeart}} Triturar rocas genera medio corazón de alma" },
  { "t", "⟨t:Geode Fossil⟩", nil, "{{ffGeodeFossil}} {{ColorTransform}}Baratija de roca (Geoda x Fósil)#↑ +1.5 Alcance#↑ +0.75 Alcance extra si llevas otra Geoda#{{ffCrush}} Da una baratija Geoda común o rara al triturarla#{{ffCrush}} Si llevas otra Geoda, da otra baratija Geoda común o rara al triturarla" },
  { "c", "⟨c:Pyromancy⟩", nil, "Aparecen a menudo bolas de fuego orbitales alrededor de Isaac, hasta tres#Pulsa dos veces disparar para lanzar una bola de fuego que deja un rastro de llamas y explota al impactar" },
  { "c", "⟨c:The Fiend Folio⟩", nil, "Invoca a un ayudante de Fiend Folio que te ayuda en la sala" },
  { "c", "⟨c:D2⟩", nil, "Lanza al suelo una moneda morada giratoria durante un rato#Los recolectables, enemigos y lágrimas que la tocan cambian" },
  { "c", "⟨c:Store Whistle⟩", nil, "Genera un cofre tienda#Los cofres tienda necesitan una llave y, al abrirse, se convierten en una tienda portátil" },
  { "c", "⟨c:The Original Dice Bag⟩", nil, "Genera 1 Dado de cristal cada 8 salas#Los Dados de cristal imitan a un dado y se rompen tras usarlos" },
  { "c", "⟨c:Lil Fiend⟩", nil, "Vuela en diagonal por la sala#Puede soltar un Esbirro de Fiend al chocar con un enemigo o una lágrima#Los esbirros atacan a los enemigos y desaparecen al limpiar la sala" },
  { "c", "⟨c:Baby Crater⟩", nil, "{{Chargeable}} Mientras disparas, Bebé Cráter crea un círculo de lágrimas#Las lágrimas salen cuando Isaac deja de disparar#3.5 de daño por lágrima" },
  { "c", "⟨c:Mrs. Spooter⟩", nil, "Spooter de tono azul que persigue a los enemigos#Dispara lágrimas a sus objetivos cada cierto tiempo#3.5 de daño por lágrima" },
  { "c", "⟨c:Randy The Snail⟩", nil, "Familiar caracol que se esconde en su concha al recibir un proyectil#Randy puede rebotar por la sala al chocar repetidamente con proyectiles" },
  { "c", "⟨c:Corn Kernel⟩", nil, "Nv1: orbital ondulante#Nv2: orbital que dispara explosiones débiles#Nv3: familiar que se teletransporta y persigue a los enemigos#Nv4: familiar que se teletransporta y dispara maíz explosivo" },
